const listAgentAllocations = `-- name: ListAgentAllocations :many
SELECT id, agent_id, user_id, username, plan_id, plan_name, traffic_bytes, duration_days, kind, created_at
FROM agent_allocation
WHERE agent_id = $1
  AND ($2::timestamptz IS NULL OR created_at >= $2::timestamptz)
  AND ($3::timestamptz IS NULL OR created_at < $3::timestamptz)
ORDER BY created_at DESC, id DESC
LIMIT $5 OFFSET $4
`

type ListAgentAllocationsParams struct {
	AgentID   int64
	FromTime  pgtype.Timestamptz
	ToTime    pgtype.Timestamptz
	RowOffset int32
	RowLimit  int32
}

func (q *Queries) ListAgentAllocations(ctx context.Context, arg ListAgentAllocationsParams) ([]AgentAllocation, error) {
	rows, err := q.db.Query(ctx, listAgentAllocations,
		arg.AgentID,
		arg.FromTime,
		arg.ToTime,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AgentAllocation{}
	for rows.Next() {
		var i AgentAllocation
		if err := rows.Scan(
			&i.ID,
			&i.AgentID,
			&i.UserID,
			&i.Username,
			&i.PlanID,
			&i.PlanName,
			&i.TrafficBytes,
			&i.DurationDays,
			&i.Kind,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

